import type { PayloadAction } from '@reduxjs/toolkit';
import { createSlice } from '@reduxjs/toolkit';
import { getInitialPage, Page, SearchCriteria } from 'src/models/owns/page';
import type { AppThunk } from 'src/store';
import Part, { PartMiniDTO } from '../models/owns/part';
import api from '../utils/api';
import { revertAll } from 'src/utils/redux';
import { StockMovementPage } from 'src/models/owns/stockMovement';
import { cancellableFetch } from 'src/utils/cancellableRequest';

const basePath = 'parts';

interface PartState {
  parts: Page<Part>;
  singlePart: Part;
  partsMini: PartMiniDTO[];
  movementsByPart: { [partId: number]: StockMovementPage };
  loadingGet: boolean;
}

const initialState: PartState = {
  parts: getInitialPage<Part>(),
  singlePart: null,
  partsMini: [],
  movementsByPart: {},
  loadingGet: false
};

const slice = createSlice({
  name: 'parts',
  initialState,
  extraReducers: (builder) => builder.addCase(revertAll, () => initialState),
  reducers: {
    getParts(state: PartState, action: PayloadAction<{ parts: Page<Part> }>) {
      const { parts } = action.payload;
      state.parts = parts;
    },
    getSinglePart(state: PartState, action: PayloadAction<{ part: Part }>) {
      const { part } = action.payload;
      state.singlePart = part;
    },
    editPart(state: PartState, action: PayloadAction<{ part: Part }>) {
      const { part } = action.payload;
      const inContent = state.parts.content.some(
        (part1) => part1.id === part.id
      );
      if (inContent) {
        state.parts.content = state.parts.content.map((part1) => {
          if (part1.id === part.id) {
            return part;
          }
          return part1;
        });
      } else {
        state.singlePart = part;
      }
    },
    updatePartEverywhere(state: PartState, action: PayloadAction<{ part: Part }>) {
      const { part } = action.payload;
      state.parts.content = state.parts.content.map((p) =>
        p.id === part.id ? part : p
      );
      if (state.singlePart?.id === part.id) state.singlePart = part;
    },
    getStockMovements(
      state: PartState,
      action: PayloadAction<{ partId: number; movements: StockMovementPage }>
    ) {
      const { partId, movements } = action.payload;
      state.movementsByPart[partId] = movements;
    },
    getPartsMini(
      state: PartState,
      action: PayloadAction<{ parts: PartMiniDTO[] }>
    ) {
      const { parts } = action.payload;
      state.partsMini = parts;
    },
    addPart(state: PartState, action: PayloadAction<{ part: Part }>) {
      const { part } = action.payload;
      state.parts.content = [part, ...state.parts.content];
    },
    deletePart(state: PartState, action: PayloadAction<{ id: number }>) {
      const { id } = action.payload;
      const partIndex = state.parts.content.findIndex((part) => part.id === id);
      if (partIndex !== -1) state.parts.content.splice(partIndex, 1);
    },
    setLoadingGet(
      state: PartState,
      action: PayloadAction<{ loading: boolean }>
    ) {
      const { loading } = action.payload;
      state.loadingGet = loading;
    },
    clearSinglePart(state: PartState, action: PayloadAction<{}>) {
      state.singlePart = null;
    }
  }
});

export const reducer = slice.reducer;

export const getParts =
  (criteria: SearchCriteria): AppThunk =>
  async (dispatch) => {
    await cancellableFetch(
      dispatch,
      'getParts',
      (signal) =>
        api.post<Page<Part>>(`${basePath}/search`, criteria, { signal }),
      (parts) => dispatch(slice.actions.getParts({ parts })),
      (loading) => dispatch(slice.actions.setLoadingGet({ loading }))
    );
  };

export const getSinglePart =
  (id: number): AppThunk =>
  async (dispatch) => {
    dispatch(slice.actions.setLoadingGet({ loading: true }));
    try {
      const part = await api.get<Part>(`${basePath}/${id}`);
      dispatch(slice.actions.getSinglePart({ part }));
    } finally {
      dispatch(slice.actions.setLoadingGet({ loading: false }));
    }
  };

export const editPart =
  (id: number, part): AppThunk =>
  async (dispatch) => {
    const partResponse = await api.patch<Part>(`${basePath}/${id}`, part);
    dispatch(slice.actions.editPart({ part: partResponse }));
  };
export const getPartsMini = (): AppThunk => async (dispatch) => {
  const parts = await api.get<PartMiniDTO[]>(`${basePath}/mini`);
  dispatch(slice.actions.getPartsMini({ parts }));
};
export const addPart =
  (part): AppThunk =>
  async (dispatch) => {
    const partResponse = await api.post<Part>(basePath, part);
    dispatch(slice.actions.addPart({ part: partResponse }));
    return partResponse;
  };
export const deletePart =
  (id: number): AppThunk =>
  async (dispatch) => {
    const partResponse = await api.deletes<{ success: boolean }>(
      `${basePath}/${id}`
    );
    const { success } = partResponse;
    if (success) {
      dispatch(slice.actions.deletePart({ id }));
    }
  };
export const clearSinglePart = (): AppThunk => async (dispatch) => {
  dispatch(slice.actions.clearSinglePart({}));
};

export const receiveStock =
  (
    partId: number,
    dto: {
      quantity: number;
      reason?: string;
      unitCost?: number;
      purchaseOrderId?: number;
    }
  ): AppThunk =>
  async (dispatch) => {
    const part = await api.post<Part>(`${basePath}/${partId}/stock/receive`, dto);
    dispatch(slice.actions.updatePartEverywhere({ part }));
    return part;
  };

export const issueStock =
  (
    partId: number,
    dto: { quantity: number; workOrderId?: number; reason?: string }
  ): AppThunk =>
  async (dispatch) => {
    const part = await api.post<Part>(`${basePath}/${partId}/stock/issue`, dto);
    dispatch(slice.actions.updatePartEverywhere({ part }));
    return part;
  };

export const countStock =
  (partId: number, dto: { counted: number; reason?: string }): AppThunk =>
  async (dispatch) => {
    const part = await api.post<Part & { variance: number }>(
      `${basePath}/${partId}/stock/count`,
      dto
    );
    dispatch(slice.actions.updatePartEverywhere({ part }));
    return part;
  };

export const getStockMovements =
  (partId: number, page: number = 0, size: number = 20): AppThunk =>
  async (dispatch) => {
    const result = await api.get<StockMovementPage>(
      `${basePath}/${partId}/stock/movements?page=${page}&size=${size}`
    );
    dispatch(slice.actions.getStockMovements({ partId, movements: result }));
    return result;
  };

export default slice;
